[2458]={"Deep Cover",20,20,8589934770,8,nil,{2460},1150,nil,nil,nil,nil,nil,"Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule. When the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute. These actions must be performed in the correct order, as Fizzule will attack and terminate "},
