[2478]={"Mission: Possible But Not Probable",24,20,8589934770,8,nil,{2458},1950,nil,nil,nil,nil,nil,"Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts. Assassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction."},
[2479]={"Hinott's Assistance",26,20,8589934770,8,nil,{2478},1050,nil,nil,nil,nil,nil,"Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott. To get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!"},
