[6626]={"A Host of Evil",35,28,0,0,nil,nil,3450,nil,nil,nil,nil,nil,"Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.\nMobs: Death's Head Cultist (33-34), Razorfen Battleguard (33-34), Razorfen Thornweaver (33-34)"},
[6629]={"Kill Grundig Darkcloud",18,12,8589934770,0,nil,{6548},1350,nil,nil,nil,nil,nil,"Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon.\nMobs: Grimtotem Brute (15-16), Grundig Darkcloud (18)"},
[6641]={"Vorsha the Lasher",23,20,8589934770,0,nil,nil,2300,nil,nil,nil,nil,nil,"Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga. If you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher."},
[6921]={"Amongst the Ruins",27,21,8589934770,0,nil,nil,2750,nil,nil,nil,nil,nil,"Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."},
[7003]={"Zapped Giants",48,45,0,0,nil,nil,4400,nil,nil,nil,nil,nil,"Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.\nDrops from: Wave Strider (47-48), Zapped Wave Strider (47-48), Zapped Land Walker (48), Deep Strider (47-49), Zapped Deep Strider (47-49) ..."},
[7028]={"Twisted Evils",47,41,0,0,nil,nil,5250,nil,nil,nil,nil,nil,"Collect 15 Theradric Crystal Carvings for Willow in Desolace.\nDrops from: The Nameless Prophet (41), Spirit of Gelk (42), Cursed Centaur (43), Spirit of Kolk (43), Spirit of Magra (43)"},
[7029]={"Vyletongue Corruption",47,41,8589934770,0,nil,nil,5250,nil,nil,nil,nil,nil,"Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village."},
[7064]={"Corruption of Earth and Seed",51,45,8589934770,0,nil,nil,6100,nil,nil,nil,nil,nil,"Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace."},
[7067]={"The Pariah's Instructions",48,39,0,0,nil,nil,5450,nil,nil,nil,nil,nil,"Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace."},
[7068]={"Shadowshard Fragments",42,39,8589934770,0,nil,nil,3450,nil,nil,nil,nil,nil,"Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.\nDrops from: Shadowshard Rumbler (40-41), Shadowshard Smasher (41-42)"},
[7441]={"Pusillin and the Elder Azj'Tordin",58,54,0,0,nil,nil,7750,nil,nil,nil,nil,nil,"Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations."},
[7481]={"Elven Legends",60,54,8589934770,0,nil,nil,8300,nil,nil,nil,nil,nil,"Search Dire Maul for Telmius Dreamseeker. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find."},
[7489]={"Lethtendris's Web",57,54,8589934770,0,nil,nil,7550,nil,nil,nil,nil,nil,"Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas."},
[7601]={"What Niby Commands",50,50,0,256,nil,nil,4700,nil,nil,nil,nil,nil,"Speak with Impsy in Felwood."},
[7721]={"Fuel for the Zapping",48,45,0,0,nil,nil,4400,nil,nil,nil,nil,nil,"Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.\nDrops from: Sea Spray (47-48), Sea Elemental (48-49)"},
[7722]={"What the Flux?",50,45,0,0,nil,nil,4700,nil,nil,nil,nil,nil,"Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge."},
[7723]={"Curse These Fat Fingers",49,45,0,0,nil,nil,4550,nil,nil,nil,nil,nil,"Hansel Heavyhands wants you to kill 20 Heavy War Golems. The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.\nMobs: Heavy War Golem (47-49)"},
[7724]={"Fiery Menace!",49,45,0,0,nil,nil,4550,nil,nil,nil,nil,nil,"Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge. Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.\nMobs: Greater Lava Spider (47-49)"},
[7727]={"Incendosaurs? Whateverosaur is More Like It",49,45,0,0,nil,nil,4550,nil,nil,nil,nil,nil,"Hansel Heavyhands wants you to kill 20 Incendosaurs. You will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge. Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.\nMobs: Incendosaur (47-49)"},
[7728]={"STOLEN: Smithing Tuyere and Lookout's Spyglass",48,45,0,0,nil,nil,4400,nil,nil,nil,nil,nil,"Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge. The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.\nDrops from: Dark Iron Steamsmith (46-47), Da"},
[7729]={"JOB OPPORTUNITY: Culling the Competition",48,45,0,0,nil,nil,4400,nil,nil,nil,nil,nil,"Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.\nMobs: Dark Iron Slaver (45-46), Dark Iron Taskmaster (47-48)"},
[7730]={"Zukk'ash Infestation",45,39,8589934770,0,nil,{2903},3900,nil,nil,nil,nil,nil,"Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.\nDrops from: Zukk'ash Wasp (44-45), Zukk'ash Worker (44-45), Zukk'ash Stinger (45-46), Zukk'ash Tunneler (45-46), Stinglasher (47)"},
[7731]={"Stinglasher",47,39,8589934770,0,nil,{2903},4200,nil,nil,nil,nil,nil,"Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.\nDrops from: Stinglasher (47)"},
[7732]={"Zukk'ash Report",48,39,8589934770,0,{7730,7731},nil,4400,nil,nil,nil,nil,nil,"Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar."},
[7734]={"Improved Quality",48,40,8589934770,0,nil,{2822},4400,nil,nil,nil,nil,nil,"Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas.\nDrops from: Lurking Feral Scar (46), Rage Scar Yeti (46-47), Ferocious Rage Scar (47-48), Elder Rage Scar (48-49)"},
[7815]={"Snapjaws, Mon!",50,44,8589934770,0,nil,nil,4700,nil,nil,nil,nil,nil,"Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task.\nMobs: Saltwater Snapjaw (49-50)"},
[7828]={"Stalking the Stalkers",48,44,8589934770,0,nil,nil,4400,nil,nil,nil,nil,nil,"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete. Markhor mentioned that the wolves hide in the wilds of the Hinterlands.\nMobs: Silvermane Howler (45-46), Silvermane Stalker (47-48)"},
[7829]={"Hunt the Savages",48,44,8589934770,0,nil,nil,4400,nil,nil,nil,nil,nil,"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete. Markhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.\nMobs: Savage Owlbeast (46-47)"},
[7830]={"Avenging the Fallen",48,44,8589934770,0,nil,nil,4400,nil,nil,nil,nil,nil,"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete. Markhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.\nDrops from: Razorbeak Skylord (46-48)"},
[7839]={"Vilebranch Hooligans",48,44,8589934770,0,nil,nil,4400,nil,nil,nil,nil,nil,"Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete. You recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock."},
[7840]={"Lard Lost His Lunch",49,44,8589934770,0,nil,nil,4550,nil,nil,nil,nil,nil,"Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete. Lard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.\nDrops from: Vilebranch Kidnapper (49)"},
[7841]={"Message to the Wildhammer",48,44,8589934770,0,nil,nil,4400,nil,nil,nil,nil,nil,"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete. You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.\nMobs: Highvale Outrunner (43-44), Highvale Scout (44-45), Highvale Marksman (45-46),"},
[7842]={"Another Message to the Wildhammer",48,44,8589934770,0,nil,{7841},5450,nil,nil,nil,nil,nil,"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete. Gryphons are known to inhabit every region of the Hinterlands.\nDrops from: Granistad (40), Kurdros (40), Wild Gryphon (40), Trained Razorbeak (40-42), Witherbark Hideskinner (42-43) ..."},
[7843]={"The Final Message to the Wildhammer",50,44,8589934770,0,nil,{7842},5900,nil,nil,nil,nil,nil,"Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete. Beware of angry Wildhammer dwarves and unruly members of the Alliance."},
[7844]={"Cannibalistic Cousins",48,44,8589934770,0,nil,nil,4400,nil,nil,nil,nil,nil,"Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 30 Vilebranch Scalpers and 15 Vilebranch Soothsayers. Return to her when this task is complete. Yayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands.\nMobs: Vilebranch Scalper (46-47), Vilebranch Soothsayer (46-47)"},
[7845]={"Kidnapped Elder Torntusk!",51,46,8589934770,0,nil,nil,4900,nil,nil,nil,nil,nil,"Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor. You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands."},
[7849]={"Separation Anxiety",50,46,8589934770,0,nil,nil,5900,nil,nil,nil,nil,nil,"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor. Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both "},
[7850]={"Dark Vessels",50,46,8589934770,0,nil,nil,5900,nil,nil,nil,nil,nil,"Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete."},
[8251]={"Magic Dust",52,50,0,128,nil,nil,5100,nil,nil,nil,nil,nil,"Bring 10 Glittering Dust to Archmage Xylem.\nDrops from: Blood Elf Surveyor (51-52), Blood Elf Reclaimer (52-53)"},
[8252]={"The Siren's Coral",52,50,0,128,nil,{8251},5100,nil,nil,nil,nil,nil,"Collect 6 Enchanted Coral and return them to Archmage Xylem.\nDrops from: Spitelash Siren (50-52)"},
[8279]={"The Twilight Lexicon",60,54,0,0,nil,{8285},8300,nil,nil,nil,nil,nil,"Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus.\nDrops from: Twilight Keeper Mayna (60), Twilight Keeper Exeter (60), Twilight Keeper Havunth (60)"},
[8280]={"Securing the Supply Lines",55,54,0,0,nil,nil,5650,nil,nil,nil,nil,nil,"Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers.\nMobs: Dredge Striker (55-56)"},
[8281]={"Stepping Up Security",57,54,0,0,nil,{8280},6000,nil,nil,nil,nil,nil,"Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers.\nMobs: Dredge Crusher (57-58)"},
[8284]={"The Twilight Mystery",58,54,0,0,nil,nil,6200,nil,nil,nil,nil,nil,"Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments."},
[8285]={"The Deserter",59,54,0,0,nil,{8284},4800,nil,nil,nil,nil,nil,"Take the restored tablet to Hermit Ortell in Silithus."},
[8287]={"A Terrible Purpose",60,54,0,0,nil,{8279},6600,nil,nil,nil,nil,nil,"Take the Decoded Tablet Parchment to Commander Mar'alith."},
[8304]={"Dearest Natalia",60,58,0,0,nil,nil,6600,nil,nil,nil,nil,nil,"Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold. Once you have gathered the requested information, return to Commander Mar'alith.\nMobs: Rutgar Glyphshaper (60), Frankal Stonebridge (60)"},
[8309]={"Glyph Chasing",60,58,0,0,nil,{8304},8300,nil,nil,nil,nil,nil,"Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive. Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task."},
[8318]={"Secret Communication",60,57,0,0,nil,nil,6600,nil,nil,nil,nil,nil,"Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold.\nDrops from: Twilight Avenger (57-59), Twilight Marauder (58-59), Twilight Geolord (58-60), Twilight Stonecaller (59-60), Twilight Master (59-60) ..."},
[8320]={"Twilight Geolords",60,60,0,0,nil,nil,6600,nil,nil,nil,nil,nil,"Kill 10 Twilight Geolords, then return to Huum Wildmane in Cenarion Hold.\nMobs: Twilight Geolord (58-60)"},
[8321]={"Vyral the Vile",60,60,0,0,nil,{8320},6600,nil,nil,nil,nil,nil,"Bring Vyral's Signet Ring to Huum Wildmane in Cenarion Hold.\nDrops from: Vyral the Vile (61)"},
[8323]={"True Believers",59,54,0,0,nil,{8279},6400,nil,nil,nil,nil,nil,"Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts\nDrops from: Twilight Avenger (57-59), Twilight Marauder (58-59), Twilight Geolord (58-60), Twilight Stonecaller (59-60), Twilight Master (59-60) ..."},
[8331]={"Aurel Goldleaf",60,60,0,0,nil,nil,660,nil,{8332},nil,nil,nil,"Speak with Aurel Goldleaf in Cenarion Hold."},
[8332]={"Dukes of the Council",60,60,0,0,nil,nil,6600,nil,nil,nil,nil,nil,"Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.\nDrops from: Crimson Templar (60), Azure Templar (60), Hoary Templar (60), Earthen Templar (60)"},
[8341]={"Lords of the Council",60,60,0,0,nil,nil,6600,nil,nil,nil,nil,62,"Bring 5 Large Brilliant Shards and 3 Abyssal Signets to Aurel Goldleaf in Cenarion Hold.\nDrops from: The Duke of Shards (62), The Duke of Zephyrs (62), The Duke of Cynders (62), The Duke of Fathoms (62)"},
[8343]={"Goldleaf's Discovery",60,60,0,0,nil,nil,660,nil,{8341},nil,nil,nil,"Speak with Aurel Goldleaf in Cenarion Hold."},
[8348]={"Signet of the Dukes",60,60,0,0,nil,{8332},8300,nil,nil,nil,nil,62,"Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.\nDrops from: The Duke of Shards (62), The Duke of Zephyrs (62), The Duke of Cynders (62), The Duke of Fathoms (62)"},
[8349]={"Bor Wildmane",60,60,0,0,nil,{8332},660,nil,{8348},nil,nil,nil,"Speak with Bor Wildmane in Cenarion Hold."},
[8351]={"Bor Wishes to Speak",60,60,0,0,nil,{8341},660,nil,{8352},nil,nil,nil,"Speak with Bor Wildmane in Cenarion Hold."},
[8352]={"Scepter of the Council",60,60,0,0,nil,{8341},9950,nil,nil,nil,nil,63,"Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.\nDrops from: Lord Skwol (63), Prince Skaldrenox (63), High Marshal Whirlaxis (63), Baron Kazum (63)"},
[8361]={"Abyssal Contacts",60,60,0,0,nil,nil,6600,nil,nil,nil,nil,nil,"Bor Wildmane at Cenarion Hold in Silithus wants you to destroy an Abyssal Templar and bring him an Abyssal Crest as proof of the deed.\nDrops from: Crimson Templar (60), Azure Templar (60), Hoary Templar (60), Earthen Templar (60)"},
[8366]={"Southsea Shakedown",45,40,0,0,nil,nil,3900,nil,nil,nil,nil,nil,"Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to kill 10 Southsea Pirates, 10 Southsea Freebooters, 10 Southsea Dock Workers and 10 Southsea Swashbucklers.\nMobs: Southsea Freebooter (44-45), Southsea Dock Worker (44-45), Southsea Swashbuckler (44-45), Southsea Pirate (44-45)"},
[8419]={"An Imp's Request",52,50,0,256,nil,nil,3800,{8420},nil,nil,nil,nil,"Bring a piece of felcloth to Impsy in Felwood.\nDrops from: Jadefire Rogue (50-51), Jadefire Felsworn (50-51), Legashi Satyr (51-52), Jadefire Shadowstalker (51-52), Moora (52) ..."},
[8460]={"Timbermaw Ally",48,45,0,0,nil,nil,4400,nil,nil,nil,nil,nil,"Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done.\nMobs: Deadwood Warrior (48-49), Deadwood Gardener (48-49), Deadwood Pathfinder (49-50)"},
[8461]={"Deadwood of the North",55,45,0,0,nil,nil,5650,nil,nil,nil,nil,nil,"Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold.\nMobs: Deadwood Den Watcher (53-54), Deadwood Shaman (53-54), Deadwood Avenger (54-55)"},
[8462]={"Speak to Nafien",55,45,0,0,nil,{8460},560,nil,nil,nil,nil,nil,"Travel north along the main road in Felwood and speak with the furbolg named Nafien. He stands guard outside the entrance to Timbermaw Hold."},
[8464]={"Winterfall Activity",58,45,0,0,nil,nil,6200,nil,nil,nil,nil,nil,"Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring.\nMobs: Winterfall Den Watcher (55-56), Winterfall Shaman (56-57), Winterfall Ursa (57-58)"},
[8465]={"Speak to Salfa",55,45,0,0,nil,{8461},560,nil,nil,nil,nil,nil,"Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold."},
[8800]={"Cenarion Battlegear",60,60,0,0,nil,nil,660,nil,nil,nil,nil,nil,"Talk to Vargus at Cenarion Hold in Silithus."},
[9124]={"Cryptstalker Armor Doesn't Make Itself...",60,55,0,0,nil,nil,6600,nil,nil,nil,nil,nil,"Huntsman Leopold at Light's Hope Chapel in the Eastern Plaguelands wants 30 Crypt Fiend Parts.\nDrops from: Crypt Fiend (53-54), Crypt Walker (55-56), Crypt Horror (57-58), Crypt Slayer (58-59), Nerubian Overseer (60)"},
[9248]={"A Humble Offering",60,58,0,0,nil,nil,6600,nil,nil,nil,nil,63,"Aurel Goldleaf at Cenarion Hold in Silithus wants you to bring her 1 Abyssal Scepter. You must also be Honored with the Cenarion Circle.\nDrops from: Lord Skwol (63), Prince Skaldrenox (63), High Marshal Whirlaxis (63), Baron Kazum (63)"},
[9416]={"Report to General Kirika",60,1,8589934770,0,nil,nil,6600,nil,nil,nil,nil,nil,"Speak with General Kirika at the Horde encampment near Hive'Regal."},
[9422]={"Scouring the Desert",60,1,8589934770,0,nil,nil,6600,nil,nil,nil,{9416},nil,"Find and deliver Silithyst to the Silithyst Extractor then speak with General Kirika at the Horde encampment near Hive'Regal.\nMobs: Silithus Dust Turnin Quest Doodad Horde (1)"},
[9665]={"Bolstering Our Defenses",60,55,8589934770,0,nil,nil,6600,nil,nil,nil,nil,nil,"Capture Crown Guard Tower, Eastwall Tower, Northpass Tower and Plaguewood Tower in the Eastern Plaguelands, then return to Emmisary Gormok at Light's Hope Chapel.\nMobs: <TXT>Northpass Capture Quest Doodad (1), <TXT>Crown Guard Capture Quest Doodad (1), <TXT>Eastwall Capture Quest Doodad (1), <TXT>Plaguewood Capture Quest Doodad (1)"},
[65593]={"Hearts of the Lovers",20,20,8589934770,256,nil,{1472},780,{1507},nil,nil,nil,22,"Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.\nDrops from: Avelina Lilly (22), Isaac Pearson (22)"},
[65597]={"The Binding",20,20,8589934770,256,nil,{65593},780,{1507},nil,nil,nil,nil,"Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.\nMobs: Summoned Incubus (20)"},
[65601]={"Love Hurts",20,20,8589934770,256,nil,{1507},780,{1472},nil,nil,nil,nil,"Speak with Magar in Orgrimmar."},
[65604]={"The Binding",20,20,8589934770,256,nil,{65610},780,{1472},nil,nil,nil,nil,"Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.\nMobs: Summoned Incubus (20)"},
[65610]={"Wish You Were Here",27,20,8589934770,256,nil,{65601},2200,{1472},nil,nil,nil,nil,"Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.\nDrops from: Shadethicket Stone Mover (25-26), Shadethicket Bark Ripper (26-27), Shadethicket Oracle (30)"},
[90902]={"Rediscovering the Light",2,2,16,2,nil,{364},170,nil,nil,nil,nil,nil,"Heal 5 Injured Deathguard with your Holy Light ability."},
[91208]={"Coming to Terms",4,4,16,2,nil,{90902},270,nil,nil,nil,nil,nil,"Find the Frightened Paladin in Deathknell."},
[91209]={"Continue Your Training",4,4,16,2,nil,nil,270,nil,nil,nil,nil,nil,"Follow the road east out of Deathknell to find the town of Brill. Report to Shari Stilwell to continue your training."},
