[97558]={"Hides for the Forsaken",11,6,8589934770,0,nil,nil,660,nil,nil,nil,nil,nil,"Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin.\nDrops from: Decrepit Darkhound (5-6), Greater Duskbat (6-7), Cursed Darkhound (7-8), Vampiric Duskbat (8-9), Vile Fin Minor Oracle (8-9) ..."},
[98070]={"Stop the Screeching",31,27,8589934770,0,nil,nil,1900,nil,nil,nil,nil,nil,"Slay 5 Screeching Harpies, 5 Screeching Roguefeather Harpies and 5 Screeching Windcaller Harpies.\nMobs: Screeching Harpy (28-29), Screeching Roguefeather (29-30), Screeching Windcaller (30)"},
[98094]={"Scout Support",25,19,8589934770,0,nil,nil,2000,nil,nil,nil,nil,nil,"High Executor Darthalia wants you to deliver updated orders to Deathstalker Masoj, south of Tarren Mill, outside of Dun Garok."},
[98251]={"Never Coming Back",23,18,8589934770,0,nil,nil,1850,nil,nil,nil,nil,nil,"Kill 6 Shadowhorn Stag and 6 Ashenvale Bear and return to Va'xug Firefure northwest of Fallen Sky Lake.\nMobs: Ashenvale Bear (21-22), Shadowhorn Stag (22-23)"},
[98252]={"A Void Path",23,18,8589934770,0,nil,nil,1850,nil,nil,nil,nil,nil,"Show Va'xug's Eye of Kilrogg the way back to the main Ashenvale road."},
[98298]={"Arugal's Folly",16,9,8589934770,0,nil,{99},880,nil,nil,nil,nil,nil,"Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher.\nDrops from: Moonrage Bloodhowler (15-16)"},
[98362]={"To Thunder Bluff",20,20,8589934624,1024,nil,nil,780,nil,nil,nil,nil,nil,"Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise."},
[98389]={"A Light in the Darkness",4,2,8589934770,0,nil,{376},270,nil,nil,nil,nil,nil,"Free 6 Webbed Victims in Night's Web Hollow for Aramis Hammerhand in Deathknell."},
[98405]={"The Great Cat Spirit",20,20,32,1024,nil,nil,780,nil,nil,nil,nil,nil,"Seek out the Great Cat Spirit in southern part Moonglade and learn what it has to share with you about the nature of the cat."},
[98430]={"The Longwalkers",8,1,8589934770,0,nil,nil,700,nil,nil,nil,nil,nil,"Help Perith Stormhoof escape Palemane Rock, and report his safety to Cairne Bloodhoof in Thunder Bluff."},
[98435]={"Thunderhorn's Report",10,4,8589934770,0,nil,{760},420,nil,nil,nil,nil,nil,"Bring Thunderhorn's Report to Arch Druid Hamuul Runetotem in Thunder Bluff."},
[98545]={"Leonid's Letter",12,10,8589934770,0,nil,{96896},910,nil,nil,nil,nil,nil,"Deliver the Sealed Letter to Glix Xizzix in the Undercity."},
[98575]={"Tainted Tablet",1,1,128,256,nil,{788},40,nil,nil,nil,nil,nil,"Read the Tainted Tablet and speak to Nartok inside the Den in the Valley of Trials."},
[98576]={"Glyphic Parchment",1,1,2,128,nil,{788},40,nil,nil,nil,nil,nil,"Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials."},
[98601]={"A Difficult Path",1,1,16,2,nil,{364},40,nil,nil,nil,nil,nil,"Read the Consecrated Scroll and speak to Aramis Hammerhand in the church in Deathknell."},
[99048]={"A Missing Hand",9,9,8589934770,0,nil,nil,780,nil,nil,nil,nil,nil,"Find Heglan Shadeeye north of Tiragarde Keep."},
[99049]={"Threat from Below",9,9,8589934770,0,nil,{99048},780,nil,nil,nil,nil,nil,"Find signs of what attacked Heglan Shadeeye."},
[99051]={"Threat from Below",11,9,8589934770,0,nil,{99049},660,nil,nil,nil,nil,nil,"Collect 9 Naga Spinefins.\nDrops from: Spitelash Scout (9-10), Spitelash Attendant (10-11)"},
[99079]={"Longwalker Malah",9,4,8589934770,0,nil,nil,780,nil,nil,nil,nil,nil,"Find Longwalker Malah Longwind east of Bloodhoof Village, near the edge of Mulgore."},
[99080]={"Drive Them Out",11,4,8589934770,0,nil,{99101},660,nil,nil,nil,nil,nil,"Kill 6 Galak Centaurs, 4 Galak Outrunners, and bring the head of Herak the Pillager to Baine Bloodhoof.\nMobs: Galak Centaur (8-9), Galak Outrunner (9-10), Herak the Pillager (11)"},
[99081]={"Grim Tidings",9,4,8589934770,0,nil,{99079},780,nil,nil,nil,nil,nil,"Bring Longwalker Malah's Report to Brave Wildrunner in Bloodhoof Village."},
[99082]={"The High Chieftain",11,4,8589934770,0,nil,{99080},660,nil,nil,nil,nil,nil,"Seek audience with High Chieftain Cairne Bloodhoof in Thunder Bluff."},
[99101]={"Our Ancient Enemy",9,4,8589934770,0,nil,{99081},780,nil,nil,nil,nil,nil,"Bring Longwalker Malah's Report to Baine Bloodhoof."},
[99108]={"Sparring Match",6,4,8589934770,0,nil,nil,405,nil,nil,nil,nil,nil,"Defeat 3 other players in duels or Novice Warriors for Tang Stonehoof."},
[99123]={"Lost in the Shadows",8,4,8589934770,0,nil,nil,700,nil,nil,nil,nil,nil,"Help Pal'juh escape Kolkar Crag and bring news of your success to Master Vornal in Sen'jin Village."},
[99134]={"Discipline",6,4,8589934770,0,nil,nil,405,nil,nil,nil,nil,nil,"Punish 5 Deathguards for Executor Zygand."},
[99142]={"Tomb Weed",11,5,8589934770,0,nil,{5482},660,nil,nil,nil,nil,nil,"Collect 5 Tomb Weed and deliver them back to Junior Apothecary Holland."},
[99144]={"Seeking Refuge",7,5,8589934770,0,nil,nil,630,nil,nil,nil,nil,nil,"Help Bareth Dawnstone escape Crusader's Outpost, and report his safety to Shari Stilwell in Brill."},
[99152]={"As Above, So Below",12,7,8589934770,0,nil,{96896},910,nil,nil,nil,nil,nil,"Collect 6 Faintly Glowing Bones for Hilda the Breaker.\nDrops from: Shadowvale Lurcher (10-12), Shadowvale Mystic (10-12), Shadowvale Mystic (11-12)"},
[99153]={"The One That Got Away",12,7,8589934770,0,nil,{96896},910,nil,nil,nil,nil,nil,"Find the Hidden Crystal Fragment beneath Shadowvale for Ephram Barbaro."},
[99411]={"Kyle's Gone Missing!",7,5,8589934770,0,nil,nil,630,nil,nil,nil,nil,nil,"Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied. Feed Kyle Tender Strider Meat and return to Ahab Wheathoof.\nMobs: Kyle the Frenzied (12)"},
}
